import"./style.css";import{Player}from"./player.js";const UI={playerBoard:document.getElementById("gameboardPlayer"),oponentBoard:document.getElementById("gameboardOponent"),toast:document.getElementById("toast")};function renderBoard(e,a){let t="<thead><tr><th></th><th>A</th><th>B</th><th>C</th><th>D</th><th>E</th><th>F</th><th>G</th><th>H</th><th>I</th><th>J</th></tr></thead>";t+="<tbody>";for(let e=0;e<10;e++){t+=`<tr><th scope='row'>${e+1}</th>`;for(let r=0;r<10;r++)a.gameboard.board[e][r]?t+=`<td data-row='${e}' data-column='${r}'>X</td>`:a.gameboard.succesful.some(e=>"[i, j]"===JSON.stringify(e))?t+=`<td class='hit' data-row='${e}' data-column='${r}'>X</td>`:a.gameboard.missed.some(a=>JSON.stringify(a)===JSON.stringify([e,r]))?t+=`<td class='missed' data-row='${e}' data-column='${r}'>X</td>`:t+=`<td data-row='${e}' data-column='${r}'></td>`;t+="</tr>"}t+="</tbody>",e.innerHTML=t}const player=Player();player.gameboard.placeShip(1,0,0),player.gameboard.placeShip(1,1,0),player.gameboard.placeShip(1,2,0);const computer=Player();computer.gameboard.placeShip(1,0,0),computer.gameboard.placeShip(1,1,0),computer.gameboard.placeShip(1,2,0);let activePlayer=player,inactivePlayer=computer;renderBoard(UI.playerBoard,player),renderBoard(UI.oponentBoard,computer),UI.oponentBoard.addEventListener("click",e=>{if("TD"===e.target.tagName){const t=e.target.dataset.row,r=e.target.dataset.column;if(inactivePlayer.gameboard.board[t][r]){if("all"===inactivePlayer.gameboard.recieveAttack(t,r))UI.toast.textContent=`${currentPlayer} won!`;else if(activePlayer=activePlayer===player?computer:player,inactivePlayer=inactivePlayer===player?computer:player,activePlayer===computer){function a(e,a){return Math.floor(Math.random()*(a-e+1))+e}const o=a(0,9),d=a(0,9);player.gameboard.recieveAttack(o,d),renderBoard(UI.oponentBoard,computer),activePlayer=activePlayer===player?computer:player,inactivePlayer=inactivePlayer===player?computer:player}renderBoard(UI.playerBoard,player)}}});